sharedconfig.ini.content:
# Darkflame Universe shared config managed by the GSA wrapper.
log_to_console={config_parameter id="log_to_console"}
log_debug_statements=0
external_ip={config_parameter id="external_ip"}
dont_generate_dcf=0
max_clients={gameserver.slot_limit}
dump_folder=C:\darkflame\dump
client_location=C:\darkflame\client
client_net_version={config_parameter id="client_net_version"}
chat_server_port=2005
database_type={config_parameter id="database_type"}
sqlite_database_path=C:\darkflame\resServer\dlu.sqlite
skip_account_creation={config_parameter id="skip_account_creation"}
